import{_ as o,o as a,c as r,a0 as t}from"./chunks/framework.B6reNh8h.js";const v=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),d={name:"explanation/architecture.md"};function s(i,e,c,n,p,l){return a(),r("div",null,[...e[0]||(e[0]=[t(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Pavo is the visualization <strong>host</strong> for the 9aia org&#39;s tool suite — the factory&#39;s screen. Named for <em>Pavo</em> — the peafowl genus; the display animal.</p><p>The core idea: <strong>products ship drivers, not UIs.</strong> A product (kuda, myco, cuora, …) ships a <code>tamias-driver-&lt;type&gt;</code> executable that speaks an ndjson JSON-RPC wire and emits a declarative <strong>ViewNode IR</strong> — a tree of typed nodes (<code>panel</code>, <code>table</code>, <code>tree</code>, <code>graph</code>, <code>form</code>, <code>kv</code>, <code>markdown</code>, <code>embed</code>, <code>row</code>, <code>column</code>) plus view-model data. Pavo&#39;s renderers — CLI, TUI, web — interpret those trees natively. There is no <code>&lt;product&gt; ui</code> per product; pavo is the single entry point, and a driver installed once visualizes on every surface.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tamias-driver-* (serve, stdio)          pavo host</span></span>
<span class="line"><span>┌──────────────────────────┐      ┌─────────────────────────────┐</span></span>
<span class="line"><span>│ manifest → routes+chrome │ ───▶ │ pavo-core Host              │</span></span>
<span class="line"><span>│ view    → ViewNode + data│ ◀─── │  discovery → manifests      │</span></span>
<span class="line"><span>│ query   → data payload   │      │  → DriverClient (1 proc/    │</span></span>
<span class="line"><span>│ render  → RenderModel    │      │    driver, timeout+restart) │</span></span>
<span class="line"><span>└──────────────────────────┘      │  → merge chrome, resolve     │</span></span>
<span class="line"><span>                                  │    &lt;driver&gt;:&lt;view&gt; links     │</span></span>
<span class="line"><span>        renderers: CLI · TUI · web│  → view-model cache          │</span></span>
<span class="line"><span>                                  └─────────────────────────────┘</span></span></code></pre></div><h2 id="the-layers" tabindex="-1">The layers <a class="header-anchor" href="#the-layers" aria-label="Permalink to &quot;The layers&quot;">​</a></h2><ul><li><strong><code>pavo-protocol</code></strong> — the public wire contract: driver manifests, ViewNode IR, RenderModel, ndjson ops. Pure serde, no I/O. The JSON Schemas in <code>protocol/v1/</code> are hand-maintained mirrors; versioning is additive-only within v1.</li><li><strong><code>pavo-core</code></strong> — host core: driver discovery (PATH + <code>&lt;tamias-home&gt;/drivers/</code>), contribution merge, per-driver <code>DriverClient</code>s, ViewNode walk/evaluate helpers, the renderer registry, the view-model TTL cache. Sync and std-only.</li><li><strong><code>pavo-cli</code></strong> (<code>pavo</code>) — the binary: <code>drivers</code>/<code>views</code>/<code>chrome</code>/ <code>view</code>/<code>query</code>/<code>serve</code>/<code>open</code> verbs, <code>--json</code> everywhere, and the protocol conformance harness. Also <code>pavo serve</code>, the localhost HTTP bridge for the web host.</li><li><strong><code>pavo-tui</code></strong> (<code>pavo-tui</code>) — the ratatui surface: driver rail, ViewNode canvas, detail pane, contribution-driven chrome.</li><li><strong><code>pavo-testkit</code></strong> — conformance: <code>FixtureDriver</code> builds fake <code>tamias-driver-*</code> executables, <code>check_driver</code> runs the wire contract suite, record/replay transcripts give renderers deterministic sessions.</li><li><strong><code>pavo-driver-config</code></strong> (<code>tamias-driver-config</code>) — first-party driver: the common config API (namespaced <code>query</code> ops over layered TOML/JSON config).</li><li><strong><code>web/</code></strong> — the Nuxt 4 SSR shell + client-side data islands, served as static files by <code>pavo serve</code>.</li><li><strong><code>examples/drivers/</code></strong> — reference drivers: <code>demo</code> (full IR + chrome), <code>myco</code> (thin proxy pattern), <code>viz-graph</code> (renderer plugin).</li></ul><table tabindex="0"><thead><tr><th>crate</th><th>layer</th><th>purpose</th></tr></thead><tbody><tr><td><code>pavo-protocol</code></td><td>domain</td><td>Wire contract — driver manifests, ViewNode IR, ndjson ops (the public API)</td></tr><tr><td><code>pavo-core</code></td><td>host</td><td>Host core — tamias driver discovery, contribution merge, per-driver clients, view-model cache</td></tr><tr><td><code>pavo-driver-config</code></td><td>adapter</td><td>tamias-driver-config — the common config API driver for the 9aia suite (pavo view driver)</td></tr><tr><td><code>pavo-testkit</code></td><td>adapter</td><td>Recorded driver sessions → conformance fixtures for all pavo surfaces</td></tr><tr><td><code>pavo-tui</code></td><td>adapter</td><td>ratatui host — chrome slots + ViewNode renderer for pavo</td></tr><tr><td><code>pavo</code></td><td>binary</td><td>pavo — visualization host: discover tamias drivers, render their views (CLI/TUI/web)</td></tr></tbody></table><h2 id="the-wire" tabindex="-1">The wire <a class="header-anchor" href="#the-wire" aria-label="Permalink to &quot;The wire&quot;">​</a></h2><p>Drivers are spawned per surface need: pavo keeps one <code>serve</code> process per driver (<code>DriverClient</code>), speaks <code>{&quot;op&quot;:…}</code> → <code>{&quot;ok&quot;:…}</code> ndjson, and caches view models briefly. Discovery is cheap — <code>manifest</code> answers without product state, so <code>pavo drivers</code> and <code>pavo views</code> work even when the underlying product isn&#39;t running. Full contract: <a href="/pavo/reference/wire-ops.html">Wire ops</a>, <a href="/pavo/reference/driver-manifest.html">Driver manifest</a>.</p><h2 id="deep-links-are-the-ui" tabindex="-1">Deep links are the UI <a class="header-anchor" href="#deep-links-are-the-ui" aria-label="Permalink to &quot;Deep links are the UI&quot;">​</a></h2><p>A view is a <code>&lt;driver&gt;:&lt;view&gt;</code> ref plus optional params. On the CLI it&#39;s an argument; on the web it&#39;s a URL (<code>/view/myco:item/id=T-001</code>) that agents and humans can drop into PRs, issues, and handoffs. The TUI takes the same ref via <code>pavo open</code>. See <a href="/pavo/tutorials/deep-links.html">Deep links</a>.</p><h2 id="why-this-shape" tabindex="-1">Why this shape <a class="header-anchor" href="#why-this-shape" aria-label="Permalink to &quot;Why this shape&quot;">​</a></h2><p>See <a href="/pavo/explanation/why-declarative.html">Why declarative views</a> and <a href="/pavo/explanation/boundaries.html">Boundaries</a>.</p>`,13)])])}const u=o(d,[["render",s]]);export{v as __pageData,u as default};
